	CONSTRAINT "yield_rule_interval_check" CHECK ("app"."financial_yield_rules"."effective_from" between date '1000-01-01' and date '9988-12-31' and ("app"."financial_yield_rules"."effective_to" is null or "app"."financial_yield_rules"."effective_to">"app"."financial_yield_rules"."effective_from")),
	CONSTRAINT "yield_rule_delay_cap_check" CHECK ("app"."financial_yield_rules"."eligibility_delay_days" between 0 and 3650 and ("app"."financial_yield_rules"."eligible_balance_cap_minor" is null or "app"."financial_yield_rules"."eligible_balance_cap_minor">0)),
	CONSTRAINT "yield_rule_tax_check" CHECK ("app"."financial_yield_rules"."tax_treatment" in ('NONE','BR_FIXED_INCOME_STANDARD','BR_SAVINGS_EXEMPT') and ("app"."financial_yield_rules"."tax_reference_date" is null or "app"."financial_yield_rules"."tax_reference_date"<="app"."financial_yield_rules"."effective_from")),
	CONSTRAINT "yield_rule_shape_check" CHECK (("app"."financial_yield_rules"."rule_type"='ZERO' and "app"."financial_yield_rules"."fixed_rate" is null and "app"."financial_yield_rules"."benchmark" is null and "app"."financial_yield_rules"."benchmark_percentage" is null and "app"."financial_yield_rules"."rate_period" is null and "app"."financial_yield_rules"."day_count_convention"='CALENDAR_365' and "app"."financial_yield_rules"."tax_treatment"='NONE') or ("app"."financial_yield_rules"."rule_type"='FIXED_RATE' and "app"."financial_yield_rules"."fixed_rate" between 0 and 10 and "app"."financial_yield_rules"."benchmark" is null and "app"."financial_yield_rules"."benchmark_percentage" is null and "app"."financial_yield_rules"."rate_period" in ('ANNUAL','MONTHLY') and "app"."financial_yield_rules"."day_count_convention" in ('CALENDAR_365','BUSINESS_252') and "app"."financial_yield_rules"."tax_treatment" in ('NONE','BR_FIXED_INCOME_STANDARD')) or ("app"."financial_yield_rules"."rule_type"='BENCHMARK_PERCENTAGE' and "app"."financial_yield_rules"."fixed_rate" is null and "app"."financial_yield_rules"."benchmark" in ('CDI','SELIC') and "app"."financial_yield_rules"."benchmark_percentage" between 0 and 10 and "app"."financial_yield_rules"."rate_period" is null and "app"."financial_yield_rules"."day_count_convention"='BUSINESS_252' and "app"."financial_yield_rules"."tax_treatment" in ('NONE','BR_FIXED_INCOME_STANDARD')) or ("app"."financial_yield_rules"."rule_type"='SAVINGS_BR' and "app"."financial_yield_rules"."fixed_rate" is null and "app"."financial_yield_rules"."benchmark" is null and "app"."financial_yield_rules"."benchmark_percentage" is null and "app"."financial_yield_rules"."rate_period" is null and "app"."financial_yield_rules"."day_count_convention"='MONTHLY_ANNIVERSARY' and "app"."financial_yield_rules"."tax_treatment"='BR_SAVINGS_EXEMPT'))
);
