-- Reviewed incremental integrity supplement. Invoker only; no privilege escalation
-- or grants. Parent row lock serializes interval checks, including direct inserts.
CREATE FUNCTION app.validate_yield_rule() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $body$
DECLARE profile_currency text; profile_status text;
BEGIN
  SELECT currency,status INTO profile_currency,profile_status
    FROM app.financial_yield_profiles WHERE id=NEW.profile_id AND auth_user_id=NEW.auth_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Yield profile ownership mismatch' USING ERRCODE='23503'; END IF;
  IF profile_status <> 'ACTIVE' THEN RAISE EXCEPTION 'Yield profile archived' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.effective_to<=OLD.effective_from OR
    (to_jsonb(NEW)-'effective_to') IS DISTINCT FROM (to_jsonb(OLD)-'effective_to')) THEN
    RAISE EXCEPTION 'Yield rules are immutable except first interval closure' USING ERRCODE='23514';
  END IF;
  IF (NEW.rule_type='FIXED_RATE' AND (NEW.fixed_rate IS NULL OR NEW.rate_period IS NULL)) OR
     (NEW.rule_type='BENCHMARK_PERCENTAGE' AND (NEW.benchmark IS NULL OR NEW.benchmark_percentage IS NULL)) THEN
    RAISE EXCEPTION 'Yield rule missing required rate' USING ERRCODE='23514';
  END IF;
  IF profile_currency<>'BRL' AND (NEW.rule_type IN ('BENCHMARK_PERCENTAGE','SAVINGS_BR') OR NEW.tax_treatment<>'NONE') THEN
    RAISE EXCEPTION 'Brazilian yield rules require BRL' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM app.financial_yield_rules r WHERE r.profile_id=NEW.profile_id AND r.id<>NEW.id
    AND daterange(r.effective_from,r.effective_to,'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN
    RAISE EXCEPTION 'Yield rule intervals overlap' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $body$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.validate_yield_rule() FROM PUBLIC,anon,authenticated;
--> statement-breakpoint
CREATE TRIGGER yield_rule_integrity BEFORE INSERT OR UPDATE ON app.financial_yield_rules FOR EACH ROW EXECUTE FUNCTION app.validate_yield_rule();
--> statement-breakpoint
CREATE FUNCTION app.validate_yield_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $body$
BEGIN
  IF NEW.id<>OLD.id OR NEW.auth_user_id<>OLD.auth_user_id OR NEW.account_id<>OLD.account_id OR NEW.currency<>OLD.currency OR NEW.created_at<>OLD.created_at OR (OLD.status='ARCHIVED' AND NEW.status<>'ARCHIVED') THEN
    RAISE EXCEPTION 'Yield profile identity and archive are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $body$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.validate_yield_profile() FROM PUBLIC,anon,authenticated;
--> statement-breakpoint
CREATE TRIGGER yield_profile_integrity BEFORE UPDATE ON app.financial_yield_profiles FOR EACH ROW EXECUTE FUNCTION app.validate_yield_profile();
